package com.hs.jxc.lgs;
import com.hs.jxc.common.db.DbRows;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.jobs.WorkItemProvider;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
@Component
public class LogisticsWorkItems implements WorkItemProvider {
 private final JdbcTemplate jdbc;public LogisticsWorkItems(JdbcTemplate jdbc){this.jdbc=jdbc;}
 private void add(List<Map<String,Object>> out,Access a,Map<String,Object> raw,String type,String label,String permission,String link){if(!a.has(permission))return;var row=DbRows.camel(raw);if(!a.canRow(row))return;var item=new LinkedHashMap<String,Object>();item.put("id",row.get("id"));item.put("todoType",type);item.put("typeLabel",label);item.put("title",label+" "+Objects.toString(row.get("docNo"),""));item.put("link",link);item.put("perm",permission);item.put("dedupKey",type+":"+row.get("id"));item.put("createdAt",Objects.toString(row.get("createdAt"),Objects.toString(row.get("bizDate"),"")));out.add(item);}
 public List<Map<String,Object>> items(Access a){var out=new ArrayList<Map<String,Object>>();for(var r:jdbc.queryForList("SELECT sh.*,sh.dest_warehouse_id warehouse_id FROM lgs_shipment sh WHERE sh.country_id=? AND EXISTS(SELECT 1 FROM lgs_shipment_line l WHERE l.country_id=sh.country_id AND l.shipment_id=sh.id AND l.pending_delivery_qty>0) ORDER BY sh.id",a.requireCountry()))add(out,a,r,"PENDING_DISPATCH","待派送","lgs:delivery:create","/logistics/deliveries");
  for(var r:jdbc.queryForList("SELECT d.*,d.dest_warehouse_id warehouse_id FROM lgs_delivery d WHERE d.country_id=? AND d.status='DISPATCHED' AND EXISTS(SELECT 1 FROM lgs_delivery_line l WHERE l.country_id=d.country_id AND l.delivery_id=d.id AND l.received_qty<l.dispatch_qty) ORDER BY d.id",a.requireCountry()))add(out,a,r,"PENDING_RECEIPT","待实收","lgs:receipt:create","/logistics/receipts");
  for(var r:jdbc.queryForList("SELECT h.*,s.dest_warehouse_id warehouse_id FROM lgs_hold h JOIN lgs_shipment s ON s.country_id=h.country_id AND s.id=h.shipment_id JOIN sys_country ct ON ct.id=h.country_id WHERE h.country_id=? AND h.status IN ('ACTIVE','PARTIAL_RELEASED') AND h.review_date<=(clock_timestamp() AT TIME ZONE ct.timezone)::date AND EXISTS(SELECT 1 FROM lgs_hold_line l WHERE l.country_id=h.country_id AND l.hold_id=h.id AND l.hold_qty>l.released_qty) ORDER BY h.id",a.requireCountry()))add(out,a,r,"HOLD_REVIEW","暂缓到期复查","lgs:hold:release","/logistics/holds");
  for(var r:jdbc.queryForList("SELECT sh.*,sh.dest_warehouse_id warehouse_id FROM lgs_shipment sh JOIN sys_country ct ON ct.id=sh.country_id WHERE sh.country_id=? AND sh.status NOT IN ('DRAFT','CANCELLED','VOIDED','COMPLETED','CLOSED') AND ct.config->>'lgs.delay.toleranceHours' ~ '^[0-9]{1,6}$' AND ((sh.planned_etd IS NOT NULL AND NOT "+LogisticsService.departedSql("sh")+" AND sh.planned_etd+make_interval(hours=>(CASE WHEN ct.config->>'lgs.delay.toleranceHours' ~ '^[0-9]{1,6}$' THEN (ct.config->>'lgs.delay.toleranceHours')::integer ELSE NULL END))<clock_timestamp()) OR (sh.planned_eta IS NOT NULL AND sh.actual_eta IS NULL AND sh.planned_eta+make_interval(hours=>(CASE WHEN ct.config->>'lgs.delay.toleranceHours' ~ '^[0-9]{1,6}$' THEN (ct.config->>'lgs.delay.toleranceHours')::integer ELSE NULL END))<clock_timestamp())) ORDER BY sh.id",a.requireCountry()))add(out,a,r,"LOGISTICS_DELAY","物流节点延误","lgs:shipment:view","/logistics/shipments/"+r.get("id"));return out;
 }
}
